package httpcaddyfile

import (
	"fmt"
	"testing"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func TestZZDebug(t *testing.T) {
	input := `(snippet) {
	@g ` + "`{http.error.status_code} == 404`" + `
}

example.com

import snippet
abort @g
`
	tokens, err := caddyfile.Tokenize([]byte(input), "Caddyfile")
	if err != nil {
		t.Fatal(err)
	}
	for _, tok := range tokens {
		fmt.Printf("TOKEN line=%d text=%q quoted=%v\n", tok.Line, tok.Text, tok.Quoted())
	}
	adapter := caddyfile.Adapter{ServerType: ServerType{}}
	_, _, err = adapter.Adapt([]byte(input), nil)
	fmt.Printf("ADAPT ERR: %v\n", err)
}

